(1, 3, 'ΛΟΓΟΤΕΧΝΙΑ-1', 'Σύμφωνα με το διήγημα της Ειρήνης Μάρρα «Τα κόκκινα λουστρίνια», ο μικρός  βιοπαλαιστής σκέφτηκε πως πρέπει να φτιάξει γοβάκια για  …', 'Τη μητέρα του', 'Την αδερφή του', 'Την κοπέλα που αγαπούσε', 'Καμία από αυτές', 3, '2026-08-23 18:32:08', '2026-08-23 18:32:08'),
(1, 3, 'ΛΟΓΟΤΕΧΝΙΑ-10', 'Το απόσπασμα «Νέα Παιδαγωγική» από την «Αναφορά στον Γκρέκο» γράφτηκε από τον …   ', 'Α. Παπαδιαμάντη', 'Μ. Καραγάτση', 'Ν. Καζαντζάκη', 'Α. Σαμαράκη', 3, '2026-08-23 18:32:08', '2026-08-23 18:32:08'),
(1, 3, 'ΛΟΓΟΤΕΧΝΙΑ-11', 'Ποιος έγραψε το «Θούριο»;   ', 'Ο Διονύσιος Σολωμός', 'Ο Ρήγας Φεραίος', 'Ο Αδαμάντιος Κοραής', 'Ο Γιάννης Μακρυγιάννης', 2, '2026-08-23 18:32:08', '2026-08-23 18:32:08'),
(1, 3, 'ΛΟΓΟΤΕΧΝΙΑ-12', 'Ποιος από τους πρωταγωνιστές του 1821 έμαθε γράμματα, για να γράψει τα απομνημονεύματά του;   ', 'Ο Θεόδωρος Κολοκοτρώνης', 'Ο Ρήγας Φεραίος', 'Ο Γιάννης Μακρυγιάννης', 'Κανείς από τους τρεις', 3, '2026-08-23 18:32:08', '2026-08-23 18:32:08'),
(1, 3, 'ΛΟΓΟΤΕΧΝΙΑ-13', 'Ο «Θούριος» του Ρήγα Φεραίου είναι ύμνος ...    ', 'Εκκλησιαστικός', 'Επαναστατικός', 'Δοξαστικός', 'Εθνικός', 2, '2026-08-23 18:32:08', '2026-08-23 18:32:08'),
(1, 3, 'ΛΟΓΟΤΕΧΝΙΑ-14', 'Ο εθνικός μας ποιητής είναι ο ...   ', 'Ρήγας  Φεραίος', 'Διονύσιος  Σολωμός', 'Κωνσταντίνος Καβάφης', 'Οδυσσέας Ελύτης', 2, '2026-08-23 18:32:08', '2026-08-23 18:32:08'),
(1, 3, 'ΛΟΓΟΤΕΧΝΙΑ-15', '«Ο Απρίλης με τον έρωτα χορεύουν και γελούνε» από τους Ελεύθερους Πολιορκημένους του Δ. Σολωμού. Εδώ έχουμε:   ', 'Ασύνδετο σχήμα', 'Υπερβολή', 'Αντίθεση', 'Προσωποποίηση', 4, '2026-08-23 18:32:08', '2026-08-23 18:32:08'),
(1, 3, 'ΛΟΓΟΤΕΧΝΙΑ-16', 'Ποιος έγραψε το μυθιστόρημα «Βίος και πολιτεία του Αλέξη Ζορμπά»;', 'Ο Στρατής Μυριβήλης', 'Ο Άγγελος Σικελιανός', 'Ο Νίκος Καζαντζάκης', 'Ο Γιώργος Θεοτοκάς', 3, '2026-08-23 18:32:08', '2026-08-23 18:32:08'),
(1, 3, 'ΛΟΓΟΤΕΧΝΙΑ-17', 'Ποιος έγραψε το «Άξιον εστί»;   ', 'Ο Γεώργιος Σεφέρης', 'Ο Νίκος Εγγονόπουλος', 'Ο Οδυσσέας Ελύτης', 'Ο Γιάννης Ρίτσος', 3, '2026-08-23 18:32:08', '2026-08-23 18:32:08'),
(1, 3, 'ΛΟΓΟΤΕΧΝΙΑ-18', 'Το έργο «Ερωτόκριτος» του Β. Κορνάρου είναι:   ', 'Τραγωδία', 'Κρητική φαρσοκωμωδία', 'Έμμετρο μυθιστόρημα', 'Θρησκευτικό δράμα', 3, '2026-08-23 18:32:08', '2026-08-23 18:32:08'),
(1, 3, 'ΛΟΓΟΤΕΧΝΙΑ-19', 'Το κείμενο του Ερωτόκριτου του Β. Κορνάρου είναι γραμμένο σε ...   ', 'Καθαρεύουσα', 'Κρητικό ιδίωμα', 'Λαϊκή  γλώσσα', 'Δημοτική γλώσσα', 2, '2026-08-23 18:32:08', '2026-08-23 18:32:08'),
(1, 3, 'ΛΟΓΟΤΕΧΝΙΑ-2', 'Ποιος έγραψε το ποιητικό έργο «Ελεύθεροι Πολιορκημένοι»;   ', 'Ο Λόρδος Μπάυρον', 'Ο Ανδρέας Κάλβος', 'Ο Διονύσιος  Σολωμός', 'Ο Κωστής Παλαμάς', 3, '2026-08-23 18:32:08', '2026-08-23 18:32:08'),
(1, 3, 'ΛΟΓΟΤΕΧΝΙΑ-20', 'Ο Ρήγας Φεραίος ονομάζεται και ...    ', 'Επτανήσιος', 'Πατρινός', 'Βελεστινλής', 'Κερκυραίος', 3, '2026-08-23 18:32:08', '2026-08-23 18:32:08'),
(1, 3, 'ΛΟΓΟΤΕΧΝΙΑ-21', 'Το δημοτικό τραγούδι «Του γιοφυριού της Άρτας» ανήκει στην κατηγορία των ...  ', 'Παραλογών', 'Ακριτικών τραγουδιών', 'Κλέφτικων τραγουδιών', 'Ιστορικών τραγουδιών', 1, '2026-08-23 18:32:08', '2026-08-23 18:32:08'),
(1, 3, 'ΛΟΓΟΤΕΧΝΙΑ-3', 'Οι Ελεύθεροι πολιορκημένοι του ομώνυμου έργου του Διονυσίου  Σολωμού είναι οι …', 'Αθηναίοι', 'Θεσσαλονικείς', 'Μεσολογγίτες', 'Θηβαίοι', 3, '2026-08-23 18:32:08', '2026-08-23 18:32:08');
INSERT INTO `questions` (`categoryId`, `subjectId`, `number`, `title`, `answer1`, `answer2`, `answer3`, `answer4`, `correctAnswer`, `createdAt`, `updatedAt`) VALUES
(1, 3, 'ΛΟΓΟΤΕΧΝΙΑ-4', 'Ποιος έγραψε το ποίημα «Ιθάκη»;   ', 'Ο Κωστής Παλαμάς', 'Ο Άγγελος Σικελιανός', 'Ο Κωνσταντίνος Καβάφης', 'Ο Γιάννης Ρίτσος', 3, '2026-08-23 18:32:08', '2026-08-23 18:32:08'),
(1, 3, 'ΛΟΓΟΤΕΧΝΙΑ-5', 'Στο παραμύθι «Το πιο γλυκό ψωμί», το ψωμί που έφτιαξε μόνος του ο βασιλιάς ήταν το πιο γλυκό του κόσμου, γιατί ...', 'Ακολούθησε μία γλυκιά συνταγή', 'Είχε γίνει με δικό του κόπο', 'Είχε βάλει πολλή ζάχαρη', 'Είχε βάλει πολύ μέλι', 2, '2026-08-23 18:32:08', '2026-08-23 18:32:08'),
(1, 3, 'ΛΟΓΟΤΕΧΝΙΑ-6', 'Σύμφωνα με το αφήγημα «Ο παππούς και το εγγονάκι» του Λ. Τολστόι πρέπει να συμπεριφερόμαστε στους ανθρώπους της τρίτης ηλικίας με:   ', 'Σεβασμό', 'Κατανόηση', 'Αγάπη', 'Όλα τα παραπάνω', 4, '2026-08-23 18:32:08', '2026-08-23 18:32:08'),
(1, 3, 'ΛΟΓΟΤΕΧΝΙΑ-7', 'Το απόσπασμα «Μία Κυριακή στην Κνωσσό» από την «Αναφορά στον Γκρέκο» γράφτηκε από τον … ', 'Βιτσέντζο Κορνάρο', 'Γιάννη Μαγκλή', 'Νίκο Καζαντζάκη', 'Ηλία Βενέζη', 3, '2026-08-23 18:32:08', '2026-08-23 18:32:08'),
(1, 3, 'ΛΟΓΟΤΕΧΝΙΑ-8', 'Η Άννα Φρανκ, η συγγραφέας του έργου «Το ημερολόγιο της Άννας Φρανκ», ήταν στην καταγωγή:    ', 'Γαλλίδα', 'Γερμανίδα', 'Εβραία', 'Ελληνίδα', 3, '2026-08-23 18:32:08', '2026-08-23 18:32:08'),
(1, 3, 'ΛΟΓΟΤΕΧΝΙΑ-9', 'Η «Ερωφίλη» είναι γραμμένη από τον ...', 'Βιτσέντζο Κορνάρο', 'Γεώργιο Χορτάτση', 'Μαρίνο Τζάνε Μπουνιαλή', 'Κρητικό λαό', 2, '2026-08-23 18:32:08', '2026-08-23 18:32:08'),
(1, 6, 'ΟΔΥΣΣΕΙΑ-1', 'Ποιο είναι το θέμα της Οδύσσειας;', 'Η επιστροφή του Αχιλλέα', 'Η επιστροφή του Οδυσσέα', 'Η επιβράβευση του Οδυσσέα', 'Η επιστροφή του Αγαμέμνονα', 2, '2026-08-23 18:32:52', '2026-08-23 18:32:52'),
(1, 6, 'ΟΔΥΣΣΕΙΑ-10', 'Ο Οδυσσέας, για να φύγει από το νησί της Καλυψώς, φτιάχνει με τη βοήθειά της ... ', 'Ένα κανό', 'Μία βάρκα', 'Μία σχεδία', 'Ένα μεγάλο πλοίο', 3, '2026-08-23 18:32:52', '2026-08-23 18:32:52'),
(1, 6, 'ΟΔΥΣΣΕΙΑ-11', 'Ποιος Θεός αποφασίζει να ταλαιπωρήσει τον Οδυσσέα, λίγο πριν φτάσει στο νησί των Φαιάκων;  ', 'Ο Δίας', 'Ο Ποσειδώνας', 'Ο Ερμής', 'Ο Απόλλωνας', 2, '2026-08-23 18:32:52', '2026-08-23 18:32:52'),
(1, 6, 'ΟΔΥΣΣΕΙΑ-12', 'Η Ινώ λυπάται τον Οδυσσέα και του δίνει, για να τον σώσει, ...', 'Ένα μαγικό φίλτρο', 'Ένα μαντήλι', 'Ένα χρυσό σταυρό', 'Ένα καράβι', 2, '2026-08-23 18:32:52', '2026-08-23 18:32:52'),
(1, 6, 'ΟΔΥΣΣΕΙΑ-13', 'Τον Οδυσσέα βρίσκει πρώτη στην παραλία η κόρη του βασιλιά των Φαιάκων, η …', 'Ελένη', 'Ινώ', 'Καλυψώ', 'Ναυσικά', 4, '2026-08-23 18:32:52', '2026-08-23 18:32:52'),
(1, 6, 'ΟΔΥΣΣΕΙΑ-14', 'Πώς λεγόταν ο βασιλιάς των Φαιάκων; ', 'Νέστορας', 'Αγχίαλος', 'Αλκίνοος', 'Μενέλαος', 3, '2026-08-23 18:32:52', '2026-08-23 18:32:52'),
(1, 6, 'ΟΔΥΣΣΕΙΑ-15', 'Ποιοι έφεραν με πλοίο τον Οδυσσέα από τη Σχερία στην Ιθάκη;  ', 'Οι Αθηναίοι', 'Οι Ατρείδες', 'Οι Λακεδαιμόνιοι', 'Οι Φαίακες', 4, '2026-08-23 18:32:52', '2026-08-23 18:32:52'),
(1, 6, 'ΟΔΥΣΣΕΙΑ-16', 'Ο Οδυσσέας πηγαίνει στο καλύβι του Εύμαιου, αφού πρώτα η Αθηνά τον μεταμορφώνει σε ...  ', 'Ναύτη', 'Ζητιάνο', 'Έμπορο', 'Θεό', 2, '2026-08-23 18:32:52', '2026-08-23 18:32:52'),
(1, 6, 'ΟΔΥΣΣΕΙΑ-17', 'Τι κάνει η Πηνελόπη, όταν της αποκαλύπτεται ο Οδυσσέας; ', 'Τον πιστεύει και τρέχει στην αγκαλιά του', 'Ζητάει αποδείξεις, για να πειστεί', 'Δεν τον πιστεύει', 'Τον διώχνει', 2, '2026-08-23 18:32:52', '2026-08-23 18:32:52'),
(1, 6, 'ΟΔΥΣΣΕΙΑ-18', 'Ο πρώτος που αναγνωρίζει τον Οδυσσέα, όταν επιστρέφει στο παλάτι μεταμφιεσμένος σε ζητιάνο είναι: ', 'Η σύζυγός του Πηνελόπη', 'Ο σκύλος του Άργος', 'Η παραμάνα του Ευρύκλεια', 'Ο γιος του Τηλέμαχος', 2, '2026-08-23 18:32:52', '2026-08-23 18:32:52'),
(1, 6, 'ΟΔΥΣΣΕΙΑ-2', 'Τι ήταν ο Όμηρος; ', 'Αοιδός', 'Ραψωδός', 'Τραγωδός', 'Ιστορικός', 2, '2026-08-23 18:32:52', '2026-08-23 18:32:52'),
(1, 6, 'ΟΔΥΣΣΕΙΑ-3', 'Πώς λεγόταν ο αοιδός στο παλάτι του Οδυσσέα;', 'Δημόδοκος', 'Μέντορας', 'Φήμιος', 'Κάλχας', 3, '2026-08-23 18:32:52', '2026-08-23 18:32:52'),
(1, 6, 'ΟΔΥΣΣΕΙΑ-4', 'Ο Ποσειδώνας μισεί τον Οδυσσέα, γιατί ...', 'Σκότωσε το γιο του, τον κύκλωπα Πολύφημο', 'Τύφλωσε το γιο του, τον κύκλωπα Πολύφημο', 'Δεν του έκανε θυσίες', 'Για όλα τα παραπάνω', 2, '2026-08-23 18:32:52', '2026-08-23 18:32:52'),
(1, 6, 'ΟΔΥΣΣΕΙΑ-5', ' Όταν η Θεά Αθηνά εμφανίζεται στον Τηλέμαχο, παίρνει τη μορφή του ... ', 'Μέντη', 'Νέστορα', 'Μενέλαου', 'Κάλχα', 1, '2026-08-23 18:32:52', '2026-08-23 18:32:52'),
(1, 6, 'ΟΔΥΣΣΕΙΑ-6', 'Όταν η Αθηνά έρχεται στην Ιθάκη, βρίσκει τον Τηλέμαχο να ...', 'Διασκεδάζει με τους μνηστήρες', 'Κάθεται μόνος και λυπημένος', 'Μαλώνει με τους μνηστήρες', 'Διώχνει τους μνηστήρες από το παλάτι', 2, '2026-08-23 18:32:52', '2026-08-23 18:32:52'),
(1, 6, 'ΟΔΥΣΣΕΙΑ-7', 'Όταν ο Ερμής πηγαίνει στην Καλυψώ, εκείνη τον υποδέχεται και τον φιλοξενεί, όπως ακριβώς κάνουν και οι άνθρωποι. Πώς λέγεται αυτό; ', 'Αναχρονισμός', 'Ανθρωποκεντρισμός', 'Ανθρωπομορφισμός', 'Εγκιβωτισμός', 3, '2026-08-23 18:32:52', '2026-08-23 18:32:52'),
(1, 6, 'ΟΔΥΣΣΕΙΑ-8', 'Ο Τηλέμαχος, γυρνώντας από τη Σπάρτη, πηγαίνει στο καλύβι του Εύμαιου του χοιροβοσκού. Ποιον βρίσκει εκεί;', 'Τον Εύμαιο', 'Τους μνηστήρες', 'Τη Θεά Αθηνά', 'Τον Οδυσσέα', 4, '2026-08-23 18:32:52', '2026-08-23 18:32:52'),
(1, 6, 'ΟΔΥΣΣΕΙΑ-9', 'Η Καλυψώ προσπαθώντας να πείσει τον Οδυσσέα να παραμείνει, του υπόσχεται ... ', 'Αθανασία', 'Πολλά χρήματα', 'Ένα πλοίο', 'Να τον κάνει βασιλιά', 1, '2026-08-23 18:32:52', '2026-08-23 18:32:52');
